                failure.set(err);
                for ev in not_run {
                    yield ev;
                }
                yield crate::AgentEvent::RunFailed { error: msg };
                return;
            }
            let plan = if plan.expected_agent() == agent_name {
                plan
            } else {
                plan.with_all_denied(&format!(
                    "agent no longer available: {}",
                    plan.expected_agent()
                ))
